// TH18 v1.00a Stage 5 道中 MainSub01 (st05.ecl.txt:1059-1074) -> GirlB01 (0349-0427).
// Local source t0 = first enmCreateM of the 10-round pair schedule.
const TIME_LIMIT: int = 2000;      // 120f opening + local 1880f window.
const OPENING_BUFFER: int = 120;
const TH18_BALL: int = 416;        // type4 Ball, source base radius 4; source color 4.

// Source EX type4 ACCEL: a=100 frames, r=rank gain, s=sentinel "current angle".
// Target set_accel is polar (speed += gain/frame along current angle).
xformdef TH18_ACCEL(gain: fx) {
    set_accel(gain);
    wait(100);
    set_accel(0fx);
}

// st05.ecl.txt:0371-0426 GirlB01_at.  Source etAim(0,1)=fixed 3-way fan,
// etAngle alpha=ANGLE_PLAYER and delta=3deg, etCount(0,3,1), etSpeed M=1 -> first endpoint.
async sub shooter() {
    var rank: int = global(GVAR_RANK);
    var speed: fx = 1.8fx;
    var gain: fx = 0fx;
    var rounds: int = 1;
    if rank == 1 { rounds = 100; gain = 0.02fx; }
    if rank == 2 { rounds = 1000; gain = 0.024fx; }
    if rank == 3 { speed = 2.2fx; rounds = 30; gain = 0.03fx; }
    wait(44);                       // source waits 44 after async entry.
    for n in 0..rounds {
        var base: angle = aim_player();   // etAngle reads ANGLE_PLAYER once per outer volley.
        for burst in 0..5 {               // source $B=5 -> five etOn calls per outer volley.
            var d: angle = 0deg;          // source fan order: center, -delta, +delta.
            for k in 0..3 {
                var a: angle = base + d;
                // Birth ANIM a=1 retreat: position -= 4*velocity (kept; animation itself omitted).
                var rx: fx = 4fx*speed*cos(a);
                var ry: fx = 4fx*speed*sin(a);
                _ = fire(TH18_BALL, 4, $self_x-rx, $self_y-ry, speed, a,
                         TH18_ACCEL(gain), none);
                if k == 0 { d = -3deg; }
                if k == 1 { d = 3deg; }
            }
            wait(3);                  // source wait(3) after each etOn.
        }
        var gap: int = 20;
        if rank == 2 { gap = 15; }
        if rank == 3 { gap = 10; }
        wait(gap);                    // source wait([-1]) per rank.
    }
}

// st05.ecl.txt:0349-0369 GirlB01.  enmCreateM spawns the +x child with mirror bit;
// movement angles below are the explicit mirror conversion (180deg - source angle).
async sub girl(mirror: int) {
    set_invuln(65535);                // invincible practice shell.
    set_hurtbox(16fx);                // source setHurtbox(32,32): 32 -> radius 16.
    set_hitbox(12fx);                 // source setHitbox(24,24): 24 -> radius 12.
    var a0: int = 2048;               // 11.25deg = source 0.19634955rad.
    var a1: int = 0;
    if mirror != 0 { a0 = 30720; a1 = 32768; }   // 168.75deg / 180deg.
    move_vel(0, a0 as angle, 1.5fx, EASE_LINEAR);
    spawn shooter();
    wait(120);
    // moveVelTime(120, mode1=t^2, angle 0, speed 0.5); mirror -> 180deg.
    move_vel(120, a1 as angle, 0.5fx, EASE_QUAD_IN);
    loop { wait(600); }               // source then loops wait(1000).
}

// st05.ecl.txt:1059-1074 MainSub01: 10 rounds, mirrored + normal pair, 44f apart.
async sub wave() {
    wait(OPENING_BUFFER);
    for i in 0..10 {
        var y1: fx = 96fx + ((rand(8192) as fx)*0.0078125fx);
        _ = spawn_enemy(224fx, y1, 500, 0, 0, 0, girl(1));
        wait(44);
        var y2: fx = 96fx + ((rand(8192) as fx)*0.0078125fx);
        _ = spawn_enemy(-224fx, y2, 500, 0, 0, 0, girl(0));
        wait(44);
    }
    wait(TIME_LIMIT - OPENING_BUFFER - 880);
    loop { wait(600); }
}

// Training shell: invisible phase owner at the original stage-control position.
async sub encounter() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
